set ys {}
set pts {}
foreach pt {{1 2} {3 4} {5 6}} {
 set y [lindex $pt 1]
 if {$y > 2} {lappend ys $y; lappend pts $pt}
}

set ys {}
set pts {}
foreach pt {{1 2} {3 4} {5 6}} {set y [lindex $pt 1]; lappend ys $y; lappend pts $pt}

set n 3; set x 0
while {$n} {set x [expr {$x + 1}]; set x [string range $x 0 end]; incr n -1}
puts $x

set x 0
foreach item {1 2 3} {set x [expr {$x + 1}]; set x [string range $x 0 end]}
puts $x

set x 0
foreach item {1 2 3} {if {$item > 0} {set x [expr {$x + 1}]; set x [string range $x 0 end]}}
puts $x
